      let h_prev = h_shared[tid];
      let h_new = (1.0 - z) * h_prev + z * n;

      h_next[tid] = h_new;

      // 5. Store hidden state into global sequence buffer
      outH[t * params.outD + params.outOffset + tid] = h_new;
